function movingAverage(values, window) {
  const out = [];
  let sum = 0;
  for (let i = 0; i < values.length; i++) {
    sum += values[i];
    if (i >= window) sum -= values[i - window];
    if (i >= window - 1) out.push(sum / window);
  }
  return out;
}

async function withBackoff(fn, retries = 5) {
  let delay = 100;
  for (let i = 0; i < retries; i++) {
    try {
      return await fn();
    } catch (e) {
      await sleep(delay);
      delay *= 2;
    }
  }
}

class LRU {
  constructor(max) { this.max = max; this.map = new Map(); }
  get(k) { return this.map.get(k); }
  set(k, v) {
    if (this.map.size >= this.max) {
      const oldest = this.map.keys().next().value;
      this.map.delete(oldest);
    }
    this.map.set(k, v);
  }
}

function overlaps(aStart, aEnd, bStart, bEnd) {
  return aStart < bEnd && bStart < aEnd;
}
function bookRoom(existing, start, end) {
  for (const b of existing) {
    if (overlaps(b.start, b.end, start, end)) return false;
  }
  return true;
}

function totalPrice(items) {
  let total = 0;
  for (const it of items) {
    total += it.price * parseInt(it.qty);
  }
  return total;
}

class Once {
  constructor() { this.handlers = []; this.fired = false; }
  on(fn) { this.handlers.push(fn); if (this.fired) fn(this.value); }
  emit(v) { this.value = v; this.fired = true; this.handlers.forEach(h => h(v)); }
}
